import * as React from 'react'
import { Link } from 'gatsby'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"
import gridColours from "../data/grid-colours.json"

// ============================================
// Types & constants
// ============================================
interface Particle {
  x: number
  y: number
  vx: number
  vy: number
  colour: string
  life: number
  maxLife: number
  size: number
}

type BrushMode = 'flow' | 'scatter' | 'wave'

interface WaveRing {
  x: number
  y: number
  colour: string
  delay: number // frames until spawn
}

const MOBILE_BREAKPOINT = 600
const MAX_PARTICLES_DESKTOP = 800
const MAX_PARTICLES_MOBILE = 400
const FLOW_RATE_DESKTOP = 5
const FLOW_RATE_MOBILE = 3
const SCATTER_BURST = 35
const WAVE_RING_COUNT = 25
const DECEL = 0.98
const GRAVITY = 0.02
const TRAIL_ALPHA = 0.08

// ============================================
// Particle spawning
// ============================================
const spawnFlow = (
  particles: Particle[],
  x: number,
  y: number,
  prevX: number,
  prevY: number,
  colour: string,
  count: number,
  max: number,
) => {
  const dx = x - prevX
  const dy = y - prevY
  const angle = Math.atan2(dy, dx)

  for (let i = 0; i < count; i++) {
    if (particles.length >= max) break
    const spread = (Math.random() - 0.5) * 1.2
    const speed = 1 + Math.random() * 2
    const life = 60 + Math.random() * 60
    particles.push({
      x: x + (Math.random() - 0.5) * 4,
      y: y + (Math.random() - 0.5) * 4,
      vx: Math.cos(angle + spread) * speed,
      vy: Math.sin(angle + spread) * speed,
      colour,
      life,
      maxLife: life,
      size: 2 + Math.random() * 3,
    })
  }
}

const spawnScatter = (
  particles: Particle[],
  x: number,
  y: number,
  colour: string,
  count: number,
  max: number,
) => {
  for (let i = 0; i < count; i++) {
    if (particles.length >= max) break
    const angle = Math.random() * Math.PI * 2
    const speed = 1.5 + Math.random() * 4
    const life = 40 + Math.random() * 80
    particles.push({
      x,
      y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      colour,
      life,
      maxLife: life,
      size: 2 + Math.random() * 4,
    })
  }
}

const spawnWaveRing = (
  particles: Particle[],
  x: number,
  y: number,
  colour: string,
  count: number,
  max: number,
) => {
  const step = (Math.PI * 2) / count
  for (let i = 0; i < count; i++) {
    if (particles.length >= max) break
    const angle = step * i + (Math.random() - 0.5) * 0.3
    const speed = 1.5 + Math.random() * 1.5
    const life = 50 + Math.random() * 50
    particles.push({
      x,
      y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      colour,
      life,
      maxLife: life,
      size: 2 + Math.random() * 2,
    })
  }
}

// ============================================
// Update & render
// ============================================
const updateParticles = (particles: Particle[]): number => {
  let alive = 0
  for (let i = 0; i < particles.length; i++) {
    const p = particles[i]
    p.x += p.vx
    p.y += p.vy
    p.vx *= DECEL
    p.vy *= DECEL
    p.vy += GRAVITY
    p.life--

    if (p.life > 0) {
      particles[alive] = p
      alive++
    }
  }
  particles.length = alive
  return alive
}

const renderParticles = (
  ctx: CanvasRenderingContext2D,
  particles: Particle[],
  width: number,
  height: number,
  dpr: number,
) => {
  // Trail overlay
  ctx.fillStyle = `rgba(10, 25, 47, ${TRAIL_ALPHA})`
  ctx.fillRect(0, 0, width * dpr, height * dpr)

  ctx.save()
  ctx.scale(dpr, dpr)

  for (const p of particles) {
    const lifeRatio = p.life / p.maxLife
    const size = lifeRatio < 0.5 ? p.size * (lifeRatio / 0.5) : p.size

    ctx.beginPath()
    ctx.arc(p.x, p.y, Math.max(size, 0.5), 0, Math.PI * 2)
    ctx.fillStyle = p.colour
    ctx.globalAlpha = lifeRatio * 0.85
    ctx.fill()
  }

  ctx.restore()
}

// ============================================
// Component
// ============================================
const ParticleDrawPage: React.FC = () => {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const wrapperRef = React.useRef<HTMLDivElement>(null)
  const particlesRef = React.useRef<Particle[]>([])
  const waveQueueRef = React.useRef<WaveRing[]>([])
  const sizeRef = React.useRef({ width: 0, height: 0 })
  const rafRef = React.useRef<number>(0)
  const pointerRef = React.useRef({
    down: false,
    x: 0,
    y: 0,
    prevX: 0,
    prevY: 0,
    colour: gridColours[0],
  })
  const modeRef = React.useRef<BrushMode>('flow')
  const maxRef = React.useRef(MAX_PARTICLES_DESKTOP)
  const flowRateRef = React.useRef(FLOW_RATE_DESKTOP)
  const frameRef = React.useRef(0)

  const [activeMode, setActiveMode] = React.useState<BrushMode>('flow')

  const pickColour = (): string =>
    gridColours[Math.floor(Math.random() * gridColours.length)]

  const handleModeChange = (mode: BrushMode) => {
    modeRef.current = mode
    setActiveMode(mode)
  }

  const handleClear = () => {
    particlesRef.current.length = 0
    waveQueueRef.current.length = 0
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    ctx.fillStyle = '#0A192F'
    ctx.fillRect(0, 0, canvas.width, canvas.height)
  }

  React.useEffect(() => {
    const canvas = canvasRef.current
    const wrapper = wrapperRef.current
    if (!canvas || !wrapper) return

    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const dpr = window.devicePixelRatio || 1
    const isMobile = window.innerWidth <= MOBILE_BREAKPOINT
    maxRef.current = isMobile ? MAX_PARTICLES_MOBILE : MAX_PARTICLES_DESKTOP
    flowRateRef.current = isMobile ? FLOW_RATE_MOBILE : FLOW_RATE_DESKTOP

    const resize = () => {
      const rect = wrapper.getBoundingClientRect()
      sizeRef.current = { width: rect.width, height: rect.height }
      canvas.width = rect.width * dpr
      canvas.height = rect.height * dpr
      canvas.style.width = `${rect.width}px`
      canvas.style.height = `${rect.height}px`
      ctx.fillStyle = '#0A192F'
      ctx.fillRect(0, 0, canvas.width, canvas.height)
    }

    resize()

    const ro = new ResizeObserver(resize)
    ro.observe(wrapper)

    // Pointer helpers
    const getPos = (e: MouseEvent | Touch) => {
      const rect = canvas.getBoundingClientRect()
      return { x: e.clientX - rect.left, y: e.clientY - rect.top }
    }

    const onPointerDown = (x: number, y: number) => {
      const colour = pickColour()
      pointerRef.current = { down: true, x, y, prevX: x, prevY: y, colour }

      const mode = modeRef.current
      const max = maxRef.current

      if (mode === 'scatter') {
        spawnScatter(particlesRef.current, x, y, colour, SCATTER_BURST, max)
      }
      if (mode === 'wave') {
        // Queue 3 staggered rings
        for (let r = 0; r < 3; r++) {
          waveQueueRef.current.push({ x, y, colour, delay: r * 6 })
        }
      }
    }

    const onPointerMove = (x: number, y: number) => {
      if (!pointerRef.current.down) return
      pointerRef.current.prevX = pointerRef.current.x
      pointerRef.current.prevY = pointerRef.current.y
      pointerRef.current.x = x
      pointerRef.current.y = y
    }

    const onPointerUp = () => {
      pointerRef.current.down = false
    }

    // Mouse events
    const onMouseDown = (e: MouseEvent) => {
      const { x, y } = getPos(e)
      onPointerDown(x, y)
    }
    const onMouseMove = (e: MouseEvent) => {
      const { x, y } = getPos(e)
      onPointerMove(x, y)
    }
    const onMouseUp = () => onPointerUp()
    const onMouseLeave = () => onPointerUp()

    // Touch events
    const onTouchStart = (e: TouchEvent) => {
      e.preventDefault()
      const touch = e.touches[0]
      if (!touch) return
      const { x, y } = getPos(touch)
      onPointerDown(x, y)
    }
    const onTouchMove = (e: TouchEvent) => {
      e.preventDefault()
      const touch = e.touches[0]
      if (!touch) return
      const { x, y } = getPos(touch)
      onPointerMove(x, y)
    }
    const onTouchEnd = (e: TouchEvent) => {
      e.preventDefault()
      onPointerUp()
    }

    canvas.addEventListener('mousedown', onMouseDown)
    canvas.addEventListener('mousemove', onMouseMove)
    canvas.addEventListener('mouseup', onMouseUp)
    canvas.addEventListener('mouseleave', onMouseLeave)
    canvas.addEventListener('touchstart', onTouchStart, { passive: false })
    canvas.addEventListener('touchmove', onTouchMove, { passive: false })
    canvas.addEventListener('touchend', onTouchEnd, { passive: false })

    // Animation loop
    const tick = () => {
      const { width, height } = sizeRef.current
      const ptr = pointerRef.current
      const mode = modeRef.current
      const max = maxRef.current
      const particles = particlesRef.current
      frameRef.current++

      // Spawn particles while drawing
      if (ptr.down) {
        if (mode === 'flow') {
          spawnFlow(particles, ptr.x, ptr.y, ptr.prevX, ptr.prevY, ptr.colour, flowRateRef.current, max)
        }
        if (mode === 'scatter' && frameRef.current % 4 === 0) {
          spawnScatter(particles, ptr.x, ptr.y, ptr.colour, 8, max)
        }
        if (mode === 'wave' && frameRef.current % 20 === 0) {
          for (let r = 0; r < 2; r++) {
            waveQueueRef.current.push({ x: ptr.x, y: ptr.y, colour: ptr.colour, delay: r * 6 })
          }
        }
      }

      // Process wave queue
      const queue = waveQueueRef.current
      let qAlive = 0
      for (let i = 0; i < queue.length; i++) {
        const ring = queue[i]
        ring.delay--
        if (ring.delay <= 0) {
          spawnWaveRing(particles, ring.x, ring.y, ring.colour, WAVE_RING_COUNT, max)
        } else {
          queue[qAlive] = ring
          qAlive++
        }
      }
      queue.length = qAlive

      updateParticles(particles)
      renderParticles(ctx, particles, width, height, dpr)

      rafRef.current = requestAnimationFrame(tick)
    }

    rafRef.current = requestAnimationFrame(tick)

    return () => {
      cancelAnimationFrame(rafRef.current)
      ro.disconnect()
      canvas.removeEventListener('mousedown', onMouseDown)
      canvas.removeEventListener('mousemove', onMouseMove)
      canvas.removeEventListener('mouseup', onMouseUp)
      canvas.removeEventListener('mouseleave', onMouseLeave)
      canvas.removeEventListener('touchstart', onTouchStart)
      canvas.removeEventListener('touchmove', onTouchMove)
      canvas.removeEventListener('touchend', onTouchEnd)
    }
  }, [])

  return (
    <div className="container">
      <Header />

      <div className="particle-draw__hero">
        <Link to="/code" className="back-link">&larr; Back to Code</Link>
        <h1>Particle Draw</h1>
        <p>Draw with flowing particles &mdash; each stroke drifts and fades</p>
        <AccentDots />
      </div>

      <div className="particle-draw__canvas-area">
        <div className="particle-draw__canvas-wrapper" ref={wrapperRef}>
          <canvas ref={canvasRef} className="particle-draw__canvas" />
        </div>
        <div className="particle-draw__controls">
          <div className="particle-draw__modes">
            {(['flow', 'scatter', 'wave'] as BrushMode[]).map(mode => (
              <button
                key={mode}
                className={`particle-draw__mode-btn${activeMode === mode ? ' particle-draw__mode-btn--active' : ''}`}
                onClick={() => handleModeChange(mode)}
              >
                {mode.charAt(0).toUpperCase() + mode.slice(1)}
              </button>
            ))}
          </div>
          <button className="particle-draw__clear-btn" onClick={handleClear}>
            Clear
          </button>
        </div>
      </div>

      <Footer />
    </div>
  )
}

export default ParticleDrawPage
